/* HRM › Recruitment › Interviews (I1–I3): list, detail + feedback modal, filter drawer. */
(function () {
  const { S, esc, acts, ins, chs } = App; const H = App.H;
  const iff = App.ui.ivf = { q: '', rid: 'All', who: 'All', status: 'All', tab: 'All', mode: 'Any', cand: '' };
  const STATUS = { Scheduled: ['t-orange', 'ri-time-line'], Confirmed: ['t-blue', 'ri-information-line'], Rescheduled: ['t-purple', 'ri-information-line'], Completed: ['t-green', 'ri-checkbox-circle-line'], Cancelled: ['t-red', 'ri-close-circle-line'] };
  const MODE = { Video: 'ri-video-on-line', 'In person': 'ri-map-pin-line', Phone: 'ri-phone-line' };
  const sorted = () => S.interviews.slice().sort((a, b) => { const ua = a.status === 'Completed' || a.status === 'Cancelled', ub = b.status === 'Completed' || b.status === 'Cancelled'; return ua - ub || (ua ? (b.day + b.time).localeCompare(a.day + a.time) : (a.day + a.time).localeCompare(b.day + b.time)); });
  const rows = () => sorted().filter(i => { const c = H.cand(i.cid); if (!c) return false; const tabOk = iff.tab === 'All' || (iff.tab === 'Upcoming' ? !['Completed', 'Cancelled'].includes(i.status) : i.status === iff.tab);
    return tabOk && (iff.rid === 'All' || c.rid === iff.rid) && (iff.who === 'All' || i.who.includes(iff.who)) && (iff.status === 'All' || i.status === iff.status) && (iff.mode === 'Any' || i.mode === iff.mode)
      && (!iff.q || (H.name(c) + ' ' + H.rec(c.rid).title).toLowerCase().includes(iff.q.toLowerCase())); });
  const fbCell = i => i.status !== 'Completed' ? '<span class="muted">Not started</span>' : i.feedback.length >= i.who.length ? '<span class="good"><i class="ri-check-line"></i> Submitted</span>' : `<span class="pending">${i.feedback.length} of ${i.who.length} submitted</span>`;
  const nActive = () => (iff.rid !== 'All') + (iff.who !== 'All') + (iff.status !== 'All') + (iff.mode !== 'Any');

  H.route('/hrm/interviews', () => {
    const today = S.interviews.filter(i => i.day === H.today && i.status !== 'Cancelled').sort((a, b) => a.time.localeCompare(b.time));
    const week = H.weekdays('2026-10-04', 5); const wk = S.interviews.filter(i => i.day >= week[0] && i.day <= week[4] && i.status !== 'Cancelled');
    const pend = S.interviews.filter(i => i.status === 'Completed' && i.feedback.length < i.who.length);
    const done = S.interviews.filter(i => i.status === 'Completed');
    const avg = (done.flatMap(i => i.feedback.map(f => f.rating)).reduce((a, b, _, arr) => a + b / arr.length, 0) || 0).toFixed(1);
    const next = today.find(i => i.status !== 'Completed');
    const cnt = k => S.interviews.filter(i => k === 'All' || (k === 'Upcoming' ? !['Completed', 'Cancelled'].includes(i.status) : i.status === k)).length;
    return H.frame({ tab: 'interviews', primary: `<button class="btn primary lg" data-act="iv-new"><i class="ri-add-circle-line"></i>Schedule interview</button>`, title: 'Interviews', sub: 'Every interview scheduled across your recruitments, with feedback status.',
      actions: `<button class="btn outlined lg" data-act="iv-actions" data-menu-anchor aria-haspopup="menu"><i class="ri-settings-3-line"></i>Actions</button><button class="btn outlined lg" data-act="iv-filter"><i class="ri-filter-3-line"></i>Filter${nActive() ? ` <span class="count on">${nActive()}</span>` : ''}</button>`,
      body: `<div class="hbody stack g16"><div class="stats">
        <div class="stat feature icon"><span class="ic"><i class="ri-briefcase-4-line"></i></span><div class="stack"><span class="caption" style="color:#fff">Today</span><span class="num">${today.length} interview${today.length === 1 ? '' : 's'}</span><span class="foot">${next ? `Next: ${esc(H.name(H.cand(next.cid)))} at ${next.time}` : 'Nothing else today'}</span></div></div>
        <div class="stat icon"><span class="ic"><i class="ri-team-line"></i></span><div class="stack"><span class="caption">This week</span><span class="num">${wk.length} scheduled</span><span class="foot">${['In person', 'Video', 'Phone'].map(m => `${wk.filter(i => i.mode === m).length} ${m.toLowerCase()}`).join(' · ')}</span></div></div>
        <button class="stat icon as-btn" data-act="iv-pending"><span class="ic red"><i class="ri-user-shared-line"></i></span><div class="stack"><span class="caption">Feedback pending</span><span class="num">${pend.length} interview${pend.length === 1 ? '' : 's'}</span><span class="foot bad">${pend.length ? 'Oldest waiting 3 days' : 'All caught up'}</span></div></button>
        <div class="stat icon"><span class="ic"><i class="ri-line-chart-line"></i></span><div class="stack"><span class="caption">Completed (30 days)</span><span class="num tnum">${done.length + 30}</span><span class="foot">Avg. rating ${avg} / 5</span></div></div></div>
        <div class="row between wrap g12"><div class="seg grey sm">${['All', 'Upcoming', 'Completed', 'Cancelled'].map(k => `<button class="${iff.tab === k ? 'on-soft' : ''}" data-act="iv-tab" data-v="${k}" aria-pressed="${iff.tab === k}">${k} <span class="count">${cnt(k)}</span></button>`).join('')}</div></div>
        <div class="filters">${App.field('Search', `<input data-in="iv-q" value="${esc(iff.q)}" placeholder="Search candidate or role">`, { cls: 'search' })}${App.select('Job opening', 'iv-rec', [{ v: 'All', t: 'All openings' }, ...S.recruitments.map(r => ({ v: r.id, t: r.title }))], iff.rid)}${App.select('Interviewer', 'iv-who', [{ v: 'All', t: 'All interviewers' }, ...S.staff.map(s => ({ v: s.id, t: s.name }))], iff.who)}${App.select('Status', 'iv-status', [{ v: 'All', t: 'All Status' }, ...Object.keys(STATUS)], iff.status)}<button class="clear-btn" data-act="iv-clear"><i class="ri-close-line"></i>Clear filters</button></div>
        <div id="iv-table">${table()}</div></div>` });
  });
  function table() { const list = rows();
    return `<div class="table-card"><div class="table-scroll"><table class="dt"><thead><tr><th>Candidate</th><th>Interviewers</th><th>Scheduled <i class="ri-arrow-down-line"></i></th><th>Duration</th><th>Mode</th><th>Status</th><th>Feedback</th><th style="text-align:right">Actions</th></tr></thead><tbody>
      ${list.length ? list.map(i => { const c = H.cand(i.cid); const [tone, ic] = STATUS[i.status]; return `<tr class="click" data-act="iv-open" data-id="${i.id}"><td><span class="person">${H.cav(c)}<span class="cell2"><span>${esc(H.name(c))}</span><small>${esc(H.rec(c.rid).title)}</small></span></span></td><td>${H.avs(i.who)}</td>
        <td class="cell2"><span class="${i.day === H.today ? 'brand' : ''}">${H.when(i)}</span><small>2026</small></td><td>${i.dur} min</td><td><span class="row g8"><i class="${MODE[i.mode]} muted"></i>${i.mode}</span></td><td><span class="chip sm filled ${tone}"><i class="${ic}"></i>${i.status}</span></td><td>${fbCell(i)}</td>
        <td style="text-align:right"><span class="row-actions"><button class="icon-btn s20" data-act="iv-open" data-id="${i.id}" aria-label="View interview"><i class="ri-eye-line"></i></button><button class="icon-btn s20" data-act="iv-edit" data-id="${i.id}" aria-label="Reschedule" ${i.status === 'Completed' || i.status === 'Cancelled' ? 'disabled' : ''}><i class="ri-pencil-line"></i></button><button class="icon-btn s20" data-act="iv-more" data-id="${i.id}" data-menu-anchor aria-label="More"><i class="ri-more-2-fill"></i></button></span></td></tr>`; }).join('')
        : `<tr class="empty-row"><td colspan="8">No interviews match. <button class="btn text brand sm" data-act="iv-clear">Clear filters</button></td></tr>`}</tbody></table></div><div class="pager"><span>Rows per page: 10</span><span class="tnum">${list.length ? `1–${list.length} of ${list.length}` : '0 of 0'}</span><span class="row g4"><button class="icon-btn s20" disabled aria-label="Previous page"><i class="ri-arrow-left-s-line"></i></button><button class="icon-btn s20" disabled aria-label="Next page"><i class="ri-arrow-right-s-line"></i></button></span></div></div>`; }
  const redraw = () => { const t = App.$('#iv-table'); if (t) t.innerHTML = table(); };
  ins['iv-q'] = el => { iff.q = el.value; redraw(); }; chs['iv-rec'] = el => { iff.rid = el.value; App.render(); }; chs['iv-who'] = el => { iff.who = el.value; App.render(); }; chs['iv-status'] = el => { iff.status = el.value; App.render(); };
  acts['iv-tab'] = el => { iff.tab = el.dataset.v; App.render(); };
  acts['iv-clear'] = () => { Object.assign(iff, { q: '', rid: 'All', who: 'All', status: 'All', tab: 'All', mode: 'Any' }); App.render(); };
  acts['iv-pending'] = () => { Object.assign(iff, { tab: 'Completed' }); App.render(); App.snack('Showing completed interviews — look for orange feedback counts.', 'info'); };
  acts['iv-new'] = () => H.schedule(H.active().find(c => c.stage === 'interview')?.id || H.active()[0].id);
  acts['iv-edit'] = el => { const i = S.interviews.find(x => x.id === el.dataset.id); H.schedule(i.cid, i.id); };
  acts['iv-actions'] = el => App.menu(el, `<button data-pick="cal"><i class="ri-calendar-line"></i>Sync EHR calendars</button><button data-pick="remind"><i class="ri-mail-line"></i>Remind for pending feedback</button><button data-pick="export"><i class="ri-download-2-line"></i>Export</button>`, v => {
    if (v === 'cal') App.snack('Calendars synced from the EHR · just now.', 'info'); if (v === 'remind') App.snack('Reminders sent to interviewers with feedback outstanding.'); if (v === 'export') App.snack('Interviews exported as CSV.', 'info'); }, { width: 270 });
  acts['iv-more'] = (el, e) => { e.stopPropagation(); const i = S.interviews.find(x => x.id === el.dataset.id); const open = !['Completed', 'Cancelled'].includes(i.status);
    App.menu(el, `<button data-pick="profile"><i class="ri-user-3-line"></i>Open candidate</button>${open ? `<button data-pick="done"><i class="ri-checkbox-circle-line"></i>Mark as completed</button><button class="danger" data-pick="cancel"><i class="ri-close-circle-line"></i>Cancel interview</button>` : ''}`, v => {
      if (v === 'profile') App.go('#/hrm/candidates/' + i.cid); if (v === 'done') { i.status = 'Completed'; App.render(); App.snack('Marked as completed — interviewers can now add feedback.'); } if (v === 'cancel') cancelIv(i); }, { width: 240 }); };
  function cancelIv(i) { const prev = i.status; i.status = 'Cancelled'; App.closeModal(); App.render(); App.snack(`Interview with ${H.name(H.cand(i.cid))} cancelled · everyone notified.`, 'success', { label: 'Undo', fn: () => { i.status = prev; App.render(); } }); }

  /* detail + feedback (I2) */
  const my = App.ui.myFb = {};
  acts['iv-open'] = el => openIv(el.dataset.id);
  function openIv(id) { const i = S.interviews.find(x => x.id === id); const c = H.cand(i.cid); const done = i.status === 'Completed';
    const mine = i.feedback.find(f => f.by === 'ma'); const d = my[id] = my[id] || { rating: 0, rec: '', text: '' }; App.ui.ifbRating = d.rating;
    const avg = i.feedback.length ? (i.feedback.reduce((a, f) => a + f.rating, 0) / i.feedback.length).toFixed(1) : null; const [tone, ic] = STATUS[i.status];
    App.dialog(`<div class="dlg-head"><div class="row g12">${H.cav(c, 'lg')}<div class="stack"><div class="row g8"><h2 id="dlg-title" class="h6" style="font-size:20px">${esc(H.name(c))}</h2><span class="chip sm filled ${tone}"><i class="${ic}"></i>${i.status}</span></div><span class="caption">${esc(H.rec(c.rid).title)} • ${esc(H.stage(c.stage).name)} stage • ${esc(i.title)}</span></div></div><button class="icon-btn s20 round" data-act="close-modal" aria-label="Close"><i class="ri-close-line"></i></button></div>
      <div class="dlg-body"><div class="mini-facts">${[['ri-calendar-line', 'Scheduled', H.when(i)], ['ri-time-line', 'Duration', i.dur + ' minutes'], [MODE[i.mode], 'Mode', i.mode], ['ri-global-line', i.mode === 'Video' ? 'Meeting link' : 'Where', i.mode === 'Video' ? '<a href="#" class="link" data-act="join">Open meeting link</a>' : i.mode === 'Phone' ? esc(c.phone) : 'Riverside clinic']].map(([ico, k, v]) => `<div><i class="${ico}"></i><span class="cell2"><small>${k}</small><span>${v}</span></span></div>`).join('')}</div>
        ${i.feedback.length ? `<div class="ai-card"><div class="row between"><b class="brand row g8"><i class="ri-sparkling-2-line"></i>Feedback summary · ${i.feedback.length} of ${i.who.length} interviewers</b><span class="row g8">${H.starsHTML(Math.round(avg), 'xs')}<b>${avg}</b></span></div><p class="body2" style="margin:6px 0 0">${i.feedback.every(f => /yes/i.test(f.rec)) ? 'Every interviewer who replied recommends progressing.' : 'Interviewers are split.'} ${esc(i.feedback[0].text.split('.')[0])}.</p></div>` : ''}
        ${i.feedback.length ? `<span class="overline strong">Interviewer feedback</span>${i.feedback.map(f => { const p = f.by === 'ma' ? { id: 'ma', name: 'Muhammad Arslan' } : H.staff(f.by); return `<div class="fb-item tight"><span class="av sm ${H.avTone(p.id)}">${p.id.toUpperCase()}</span><div class="grow stack g4"><div class="row between"><span class="row g8"><b style="font-weight:500">${esc(p.name)}</b>${H.starsHTML(f.rating, 'xs')}${App.chip(f.rec, 't-green', 'sm filled')}</span><span class="caption">${esc(f.at)}</span></div><span class="body2">${esc(f.text)}</span></div></div>`; }).join('')}` : ''}
        ${done && !mine ? `<div class="subcard stack g12"><div class="row g8"><b>Your feedback</b>${App.chip('Pending', 't-orange', 'sm filled')}</div><div class="row g24 wrap top"><div class="stack g8"><span class="body2">Rating</span>${H.starsEdit('ifb', d.rating)}</div><div class="stack g8"><span class="body2">Recommendation</span><div class="seg sm">${['Strong no', 'No', 'Yes', 'Strong yes'].map(r => `<button class="${d.rec === r ? 'on' : ''}" data-act="ifb-rec" data-id="${id}" data-v="${r}" aria-pressed="${d.rec === r}">${r}</button>`).join('')}</div></div></div>
          ${App.field('', `<textarea rows="3" data-in="ifb-text" data-id="${id}" placeholder="What stood out? What should the next interviewer probe?" aria-label="Your feedback">${esc(d.text)}</textarea>`, { cls: 'multi' })}</div>` : !done && i.status !== 'Cancelled' ? `<div class="al info"><i class="ri-information-line"></i><div class="txt">Feedback opens once the interview has taken place.</div></div>` : ''}</div>
      <div class="dlg-foot">${i.status !== 'Cancelled' && !done ? `<button class="btn text" style="color:var(--error);margin-right:auto" data-act="iv-cancel" data-id="${id}">Cancel interview</button>` : '<span style="margin-right:auto"></span>'}${i.status !== 'Cancelled' ? `<button class="btn outlined lg" data-act="iv-edit" data-id="${id}">Reschedule</button>` : ''}${done && !mine ? `<button class="btn primary lg" data-act="ifb-go" data-id="${id}">Submit feedback</button>` : `<button class="btn primary lg" data-go="#/hrm/candidates/${c.id}/interviews" data-act="close-go" >Open candidate</button>`}</div>`, { width: 720 }); }
  acts['close-go'] = el => { App.closeModal(); App.go(el.dataset.go); };
  acts['iv-cancel'] = el => cancelIv(S.interviews.find(x => x.id === el.dataset.id));
  acts['ifb-rec'] = el => { my[el.dataset.id].rating = App.ui.ifbRating; my[el.dataset.id].rec = el.dataset.v; openIv(el.dataset.id); };
  ins['ifb-text'] = el => { my[el.dataset.id].text = el.value; };
  acts['ifb-go'] = el => { const id = el.dataset.id; const d = my[id]; d.rating = App.ui.ifbRating; if (!d.rating || !d.rec) { App.snack('Add a rating and a recommendation first.', 'error'); return; }
    const i = S.interviews.find(x => x.id === id); i.feedback.push({ by: 'ma', rating: d.rating, rec: d.rec, text: d.text.trim() || '—', at: '08 Oct, ' + new Date().toTimeString().slice(0, 5) }); if (!i.who.includes('ma')) i.who.push('ma');
    delete my[id]; App.closeModal(); App.render(); App.snack('Feedback submitted — the hiring team can see it now.'); };
  S.staff.push({ id: 'ma', name: 'Muhammad Arslan', role: 'Business Manager', free: 4 });

  /* filter drawer (I3) */
  let fd = null;
  acts['iv-filter'] = () => { fd = Object.assign({}, iff); drawF(); };
  function drawF() { const n = (fd.rid !== 'All') + (fd.who !== 'All') + (fd.status !== 'All') + (fd.mode !== 'Any');
    App.drawer(`<div class="dlg-head"><div class="row g8"><i class="ri-filter-3-line brand"></i><h2 id="dlg-title" class="h6" style="font-size:20px">Filter interviews</h2>${n ? App.chip(n + ' active', 't-green', 'sm filled') : ''}</div><button class="icon-btn s20 round" data-act="close-modal" aria-label="Close"><i class="ri-close-line"></i></button></div>
      <div class="dlg-body"><span class="overline strong">Who</span>${App.field('Candidate', `<input data-in="ivf-q" value="${esc(fd.q)}" placeholder="Search candidates…">`)}${App.select('Job opening', 'ivf-rec', [{ v: 'All', t: 'Any' }, ...S.recruitments.map(r => ({ v: r.id, t: r.title }))], fd.rid)}${App.select('Interviewer', 'ivf-who', [{ v: 'All', t: 'Anyone' }, ...S.staff.map(s => ({ v: s.id, t: s.name }))], fd.who)}
        <span class="overline strong">Format</span><span class="body2">Mode</span><div class="seg grey full">${['Any', 'Video', 'In person', 'Phone'].map(m => `<button class="${fd.mode === m ? 'on-soft' : ''}" data-act="ivf-mode" data-v="${m}" aria-pressed="${fd.mode === m}">${m}</button>`).join('')}</div>${App.select('Status', 'ivf-status', [{ v: 'All', t: 'Any' }, ...Object.keys(STATUS)], fd.status)}
        <span class="overline strong">When</span><div class="g2">${App.field('From', '<input type="date">')}${App.field('Till', '<input type="date">')}</div></div>
      <div class="dlg-foot"><button class="btn text" style="color:var(--error);margin-right:auto" data-act="ivf-clear">Clear all</button><button class="btn outlined lg" data-act="close-modal">Cancel</button><button class="btn primary lg" data-act="ivf-go">Apply filters</button></div>`); }
  ins['ivf-q'] = el => { fd.q = el.value; }; chs['ivf-rec'] = el => { fd.rid = el.value; drawF(); }; chs['ivf-who'] = el => { fd.who = el.value; drawF(); }; chs['ivf-status'] = el => { fd.status = el.value; drawF(); };
  acts['ivf-mode'] = el => { fd.mode = el.dataset.v; drawF(); };
  acts['ivf-clear'] = () => { Object.assign(fd, { q: '', rid: 'All', who: 'All', status: 'All', mode: 'Any' }); drawF(); };
  acts['ivf-go'] = () => { Object.assign(iff, fd); App.closeModal(); App.render(); };
})();
